meta.script:
(function () {
  if (typeof document === "undefined") return;
  var root = document.documentElement;
  if (!root) return;
  var storageKey = root.getAttribute("data-cookie-consent-key") || "ones_cookie_consent";
  var version = root.getAttribute("data-cookie-consent-version") || "2025-11-12";
  var maxAgeSeconds = 60 * 60 * 24 * 365;

  var readCookie = function (key) {
    try {
      var raw = document.cookie
        .split(";")
        .map(function (entry) { return entry.trim(); })
        .find(function (entry) { return entry.indexOf(key + "=") === 0; });
      if (!raw) return null;
      return decodeURIComponent(raw.split("=").slice(1).join("="));
    } catch (error) {
      return null;
    }
  };

  var readStoredConsent = function () {
    var value = null;
    try {
      value = window.localStorage && window.localStorage.getItem(storageKey);
    } catch (error) {
      value = null;
    }
    if (!value) {
      value = readCookie(storageKey);
    }
    if (!value) return null;
    try {
      var parsed = JSON.parse(value);
      if (!parsed || parsed.version !== version) return null;
      return parsed;
    } catch (error) {
      return null;
    }
  };

  var setConsentStatus = function () {
    root.setAttribute("data-cookie-consent-status", "set");
  };

  if (readStoredConsent()) {
    setConsentStatus();
  }

  var persistConsent = function (selection) {
    var consent = {
      strictlyNecessary: true,
      functionality: !!selection.functionality,
      analytics: !!selection.analytics,
      updatedAt: new Date().toISOString(),
      version: version
    };
    var json = JSON.stringify(consent);
    try {
      if (window.localStorage) {
        window.localStorage.setItem(storageKey, json);
      }
    } catch (error) {
      // Ignore storage errors
    }
    try {
      document.cookie = storageKey + "=" + encodeURIComponent(json)
        + "; path=/; max-age=" + maxAgeSeconds + "; SameSite=Lax";
    } catch (error) {
      // Ignore cookie errors
    }
    setConsentStatus();
  };

  var handleClick = function (event) {
    var target = event.target;
    if (!target) return;
    var node = target.nodeType === 1 ? target : target.parentNode;
    while (node && node !== document) {
      if (node.getAttribute) {
        var action = node.getAttribute("data-cookie-consent-action");
        if (action === "accept") {
          persistConsent({ functionality: true, analytics: true });
          return;
        }
        if (action === "settings") {
          if (!window.__ONES_COOKIE_CONSENT_READY__) {
            window.__ONES_COOKIE_CONSENT_PENDING_SETTINGS__ = true;
          }
          return;
        }
      }
      node = node.parentNode;
    }
  };

  document.addEventListener("click", handleClick, true);
})();

window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('consent', 'default', {
  ad_storage: 'denied',
  ad_user_data: 'denied',
  ad_personalization: 'denied',
  analytics_storage: 'denied',
  functionality_storage: 'denied',
  personalization_storage: 'denied',
  security_storage: 'granted',
  wait_for_update: 500
});
gtag('set', 'ads_data_redaction', true);
gtag('set', 'url_passthrough', true);
